	ResolveOAuthAccess(context.Context, *OAuthAccessTokenParamsRequest) (*OAuthAccessReply, error)
	GetAppCache(context.Context, *ResourceIDRequest) (*AppSupplierAccessReply, error)
	// 登录页仅读应用展示字段。
	GetAppDisplay(context.Context, *ResourceIDRequest) (*AppDisplayReply, error)
	// [免鉴权] 获取当前时间戳 秒
	GetTimestamp(context.Context, *emptypb.Empty) (*v1.Str, error)
	// [免鉴权] 创建 ID
	CreateID(context.Context, *emptypb.Empty) (*v1.Str, error)
	// [免鉴权] 为已登记的客户端签发五分钟内有效的单次口令挑战与公钥。响应禁止缓存。
	GetPasswordKey(context.Context, *PasswordKeyRequest) (*PasswordKeyReply, error)
	// [免权限] 加密数据
	Encrypt(context.Context, *EncryptRequest) (*v1.Str, error)
	// [免权限] 获取上传凭证
	GetUploadCredential(context.Context, *v11.GetUploadCredentialByMicroRequest) (*v11.GetUploadCredentialReply, error)
	// [免鉴权] 获取图片验证码
	GetImageCaptcha(context.Context, *ImageRequest) (*v12.ImageCaptchaReply, error)
	// [免鉴权] 获取当前租户的认证公开配置
	GetAuthConfig(context.Context, *emptypb.Empty) (*AuthConfigReply, error)
	// [免鉴权] 账号登录 基于安全考虑默认不开启
	Login(context.Context, *LoginRequest) (*UserAuthReply, error)
	// [免鉴权] 账号注册 基于安全考虑默认不开启
	Join(context.Context, *JoinRequest) (*UserAuthReply, error)
	// [免权限] 退出登录
	Logout(context.Context, *emptypb.Empty) (*v1.Bool, error)
	// [免权限] 获取我的信息
	GetMyInfo(context.Context, *MyInfoRequest) (*UserAuthReply, error)
	// [免鉴权] 获取手机验证码
	GetPhoneCaptcha(context.Context, *PhoneCaptchaRequest) (*v12.IssueChallengeResponse, error)
	// [免权限] 获取当前用户绑定手机号的验证码
	// 需登录；未绑定手机号则报错；底层调用 base-safe。
	GetMyPhoneCaptcha(context.Context, *MyPhoneCaptchaRequest) (*v12.IssueChallengeResponse, error)
	// [免权限] 校验当前用户绑定手机号的验证码
	// 需登录；未绑定手机号则报错；底层调用 base-safe。
	VerifyMyPhoneCaptcha(context.Context, *VerifyMyPhoneCaptchaRequest) (*v1.Bool, error)
	// [免鉴权] 通过手机验证码登录
	LoginByPhone(context.Context, *PhoneRequest) (*UserAuthReply, error)
	// [免鉴权] 获取邮箱验证码
	GetMailCaptcha(context.Context, *MailCaptchaRequest) (*v12.IssueChallengeResponse, error)
	// [免鉴权] 通过邮箱验证码登录
	LoginByMail(context.Context, *MailRequest) (*UserAuthReply, error)
	// [免鉴权] 微信小程序 code2Session
	WechatMiniCode2Session(context.Context, *v13.MiniCode2SessionRequest) (*v13.MiniCode2SessionReply, error)
	// [免鉴权] 通过微信小程序 code 登录
	LoginByWechatMiniCode(context.Context, *v13.MiniCode2SessionRequest) (*UserAuthReply, error)
	// [免鉴权] 通过微信小程序手机号登录
	LoginByWechatMiniPhone(context.Context, *v13.MiniGetPhoneNumberRequest) (*UserAuthReply, error)
	// [免权限] 绑定手机号
	BindPhone(context.Context, *PhoneRequest) (*UserAuthReply, error)
	// [免权限] 绑定微信手机号
	BindPhoneByWechat(context.Context, *v13.MiniGetPhoneNumberRequest) (*UserAuthReply, error)
	// [免权限] 绑定微信小程序
	BindWechatMini(context.Context, *v13.MiniCode2SessionRequest) (*v1.Bool, error)
	// [免权限] 判断是否已经绑定
	IsBind(context.Context, *emptypb.Empty) (*v1.Bool, error)
	// [免权限] 注销账号
	Destroy(context.Context, *emptypb.Empty) (*v1.Bool, error)
	// [免权限] 更新我的头像
	UpdateMyAvatar(context.Context, *UpdateMyAvatarRequest) (*UserPortalDetailReply, error)
	// [免权限] 更新我的信息
	UpdateMyInfo(context.Context, *UpdateMyInfoRequest) (*UserPortalDetailReply, error)
	// [免权限] 初始密码
	InitPassword(context.Context, *InitPasswordRequest) (*v1.Bool, error)
	// [免权限] 更新密码
	UpdatePassword(context.Context, *UpdatePasswordRequest) (*v1.Bool, error)
	// [免鉴权] 重置密码
	ResetPassword(context.Context, *ResetPasswordRequest) (*v1.Bool, error)
	// [免权限] OAuth 接受登录请求
	OAuthAcceptLogin(context.Context, *OAuthLoginRequest) (*OAuthRedirectResponse, error)
	// [免权限] OAuth 接受同意请求
	OAuthAcceptConsent(context.Context, *OAuthConsentRequest) (*OAuthRedirectResponse, error)
	// [免鉴权] 内部 OAuth 通过 code 获取 user token
	OAuthGetUserToken(context.Context, *OAuthCodeRequest) (*UserAuthReply, error)
	// [免鉴权] OAuth 接受注销请求
	OAuthAcceptLogout(context.Context, *OAuthLogoutRequest) (*OAuthRedirectResponse, error)
	// [免鉴权] 第三方 OAuth 获取 access token（转发到第三方服务）
	ThirdOAuthAccessToken(context.Context, *ThirdOAuthAccessTokenRequest) (*ThirdOAuthTokenResponse, error)
	// [免鉴权] 第三方 OAuth 刷新 token（转发到第三方服务）
	ThirdOAuthRefreshToken(context.Context, *ThirdOAuthRefreshTokenRequest) (*ThirdOAuthTokenResponse, error)
	// [免鉴权] 第三方 OAuth 根据 token 获取用户信息（转发到第三方服务）
	// token 可以从 Authorization header 或请求参数中获取
	ThirdOAuthUser(context.Context, *ThirdOAuthUserRequest) (*structpb.Struct, error)
	// [免鉴权] 通过第三方的 OAuth code 登录用户
	ThirdOAuthLoginByCode(context.Context, *ThirdOAuthAccessTokenRequest) (*UserAuthReply, error)
	// [免鉴权] OAuth 通过 code 获取 access token
	OAuthGetAccessToken(context.Context, *OAuthTokenRequest) (*OAuthTokenReply, error)
	// [免鉴权] OAuth 通过 access token 获取 用户信息
	OAuthGetUserInfo(context.Context, *OAuthAccessTokenParamsRequest) (*UserPortalDetailReply, error)
